import React from 'react';
import { Meta, Story } from '@storybook/react';
import { Breadcrumb } from '../..';

export default {
  title: 'Navigation/Breadcrumb/Root',
  component: Breadcrumb.Root,
  parameters: {
    docs: {
      description: {
        component:
          'The `Breadcrumb.Root` component does not have any props. It is supposed to be used with `Breadcrumb.HomeItem` and `Breadcrumb.Item` subcomponents. <br><br>How to install: `yarn add @hexa-ui/components`<br><br>How to import: `import { Breadcrumb } from "@hexa-ui/components"`<br><br>How to use: `Breadcrumb.Root`, `Breadcrumb.HomeItem` and `Breadcrumb.Item` or destructure it `{ Root, HomeItem, Item } = Breadcrumb`',
      },
    },
  },
} as Meta;

export const BreadcrumbExample: Story = () => (
  <Breadcrumb.Root>
    <Breadcrumb.HomeItem asChild>
      <a
        href="/?path=/docs/admin-portal-shared-components-breadcrumb-breadcrumb--breadcrumb-example"
        onClick={() => alert('User clicked on home')}
      >
        Home
      </a>
    </Breadcrumb.HomeItem>
    <Breadcrumb.Item asChild>
      <a
        href="/?path=/docs/admin-portal-shared-components-breadcrumb-breadcrumb--breadcrumb-example"
        onClick={() => alert('User clicked on Page Name 1')}
      >
        Page Name 1
      </a>
    </Breadcrumb.Item>
    <Breadcrumb.Item href="/?path=/docs/admin-portal-shared-components-breadcrumb-breadcrumb--breadcrumb-example">
      Page Name 2
    </Breadcrumb.Item>
    <Breadcrumb.Item isCurrentPage>Current Page</Breadcrumb.Item>
  </Breadcrumb.Root>
);

export const WithUniquePage: Story = () => (
  <Breadcrumb.Root>
    <Breadcrumb.HomeItem href="/?path=/docs/admin-portal-shared-components-breadcrumb-breadcrumb--with-unique-page" />
    <Breadcrumb.Item isCurrentPage>Current Page</Breadcrumb.Item>
  </Breadcrumb.Root>
);
